def is_samepatterns(colors, patterns):
    colors = list(colors)
    patterns = list(patterns)
    if len(colors) != len(patterns):
        return False
    # Order-preserving lists of pairs; works for unhashable items too.
    c_keys, c_vals = [], []
    p_keys, p_vals = [], []
    for c, p in zip(colors, patterns):
        if c in c_keys:
            if c_vals[c_keys.index(c)] != p:
                return False
        else:
            c_keys.append(c)
            c_vals.append(p)
        if p in p_keys:
            if p_vals[p_keys.index(p)] != c:
                return False
        else:
            p_keys.append(p)
            p_vals.append(c)
    return True

