    d = [0] * (n + 1)
    for i in range(1, n // 2 + 1):
        for j in range(2 * i, n + 1, i):
            d[j] += i
    total = 0
    for a in range(2, n + 1):
        b = d[a]
        if b != a and b <= n and d[b] == a:
            total += a
    return total

