def _dsum(m):
    if m < 2:
        return 0
    s = 1
    i = 2
    while i * i <= m:
        if m % i == 0:
            s += i
            if i != m // i:
                s += m // i
        i += 1
    return s


def amicable_numbers_sum(limit):
    found = set()
    for a in range(2, limit + 1):
        if a in found:
            continue
        b = _dsum(a)
        if b != a and _dsum(b) == a:
            found.add(a)
            found.add(b)
    return sum(found)

