def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0
    inc = list(arr)
    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i] and inc[j] + arr[i] > inc[i]:
                inc[i] = inc[j] + arr[i]
    dec = list(arr)
    for i in range(n - 1, -1, -1):
        for j in range(n - 1, i, -1):
            if arr[j] < arr[i] and dec[j] + arr[i] > dec[i]:
                dec[i] = dec[j] + arr[i]
    return max(inc[i] + dec[i] - arr[i] for i in range(n))

