def lps(s, *_):
    s = list(s) if s is not None else []
    n = len(s)
    if n == 0:
        return 0
    # dp[j] = LPS of s[i..j], rolled over i (O(n) memory)
    dp = [0] * n
    for i in range(n - 1, -1, -1):
        prev = 0          # dp_old[i+1][j-1]
        dp[i] = 1
        for j in range(i + 1, n):
            tmp = dp[j]   # dp_old[i+1][j]
            if s[i] == s[j]:
                dp[j] = prev + 2
            else:
                dp[j] = max(dp[j], dp[j - 1])
            prev = tmp
    return dp[n - 1]

