def maxAverageOfPath(cost):
    n = len(cost)
    if n == 0:
        return 0
    dp = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                dp[i][j] = cost[0][0]
            else:
                best = max(dp[i-1][j] if i else float('-inf'), dp[i][j-1] if j else float('-inf'))
                dp[i][j] = best + cost[i][j]
    return dp[-1][-1] / (2*n - 1)

