def maxAverageOfPath(cost):
    if not cost or not cost[0]:
        return 0
    m, k = len(cost), len(cost[0])
    NEG = float('-inf')
    dp = [[NEG]*k for _ in range(m)]
    for i in range(m):
        for j in range(k):
            if i == 0 and j == 0:
                dp[i][j] = cost[0][0]
            else:
                up = dp[i-1][j] if i else NEG
                left = dp[i][j-1] if j else NEG
                dp[i][j] = max(up, left) + cost[i][j]
    return dp[-1][-1] / (m + k - 1)

