def common_in_nested_lists(nestedlist):
    if not nestedlist:
        return []
    try:
        return list(set.intersection(*map(set, nestedlist)))
    except TypeError:
        # unhashable elements: fall back to list membership
        first, rest = nestedlist[0], nestedlist[1:]
        out = []
        for x in first:
            if x not in out and all(x in r for r in rest):
                out.append(x)
        return out

