            (90, 'xc'), (50, 'l'), (40, 'xl'), (10, 'x'), (9, 'ix'),
            (5, 'v'), (4, 'iv'), (1, 'i')]
    res = ''
    for v, s in vals:
        while number >= v:
            res += s
            number -= v
    return res

