def rounded_avg(n, m):
    if n > m:
        return -1
    q, rem = divmod(n + m, 2)
    if rem and q % 2 == 1:
        q += 1  # half rounds to even, same as Python's round()
    return bin(q)

def sub_list(a, b):
    result = []
    for x, y in zip(a, b):
        if isinstance(x, (list, tuple)) and isinstance(y, (list, tuple)):
