import cmath


def convert(numbers, imag=None):
    if imag is not None:
        numbers = complex(numbers, imag)
    elif isinstance(numbers, (tuple, list)) and len(numbers) == 2:
        numbers = complex(numbers[0], numbers[1])
    elif isinstance(numbers, str):
        numbers = complex(numbers.replace(" ", ""))
    r, phi = cmath.polar(numbers)
    return (r, phi)

