def find_solution(a, b, n):
    if a > 0 and b > 0 and n >= 0:
        for x in range(n // a + 1):
            r = n - a * x
            if r % b == 0:
                return (x, r // b)
        return None
    def eg(a, b):
        if b == 0:
            return (abs(a), (1 if a >= 0 else -1), 0)
        g, x, y = eg(b, a % b)
        return (g, y, x - (a // b) * y)
