def find_solution(a, b, n):
    # Search x = 0, 1, 2, ... (smallest non-negative x first).
    if a > 0 and b > 0:
        i = 0
        while i * a <= n:
            if (n - i * a) % b == 0:
                return (i, (n - i * a) // b)
            i += 1
        return None
    # Degenerate / non-positive coefficients: extended Euclid.
    def eg(a, b):
        if b == 0:
            return (abs(a), (1 if a >= 0 else -1), 0)
        g, x, y = eg(b, a % b)
        return (g, y, x - (a // b) * y)
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    g, x, y = eg(a, b)
    if n % g:
        return None
    k = n // g
    return (x * k, y * k)

