def tuple_to_int(nums):
    def flat(x):
        if isinstance(x, (tuple, list)):
            for y in x:
                yield from flat(y)
        else:
            yield x

    s = "".join(str(int(n)) for n in flat(nums))
    return int(s) if s else 0

